  "implementation": "def solve(case):
    import json
    payload = case['payload']
    nodes = payload['nodes']
    required_symbols = set(payload['required_symbols'])
    # Validate nodes
    node_map = {}
    children = {}
    for node in nodes:
        nid = node['id']
        if nid in node_map:
            raise ValueError('Duplicate node id: ' + nid)
        node_map[nid] = node
        children[nid] = []
        for key in ('id','parent','symbol','depth','removable','utility'):
            if key not in node:
                raise ValueError('Missing field ' + key + ' in node ' + nid)
        if not isinstance(node['removable'], bool):
            raise ValueError('removable must be bool')
        if not isinstance(node['depth'], int):
            raise ValueError('depth must be int')
        if not isinstance(node['utility'], (int,float)):
            raise ValueError('utility must be numeric')
    # Validate parent references and build children lists
    root_id = None
    for nid, node in node_map.items():
        pid = node['parent']
        if pid is None:
            if root_id is not None:
                raise ValueError('Multiple roots')
            root_id = nid
        else:
            if pid not in node_map:
                raise ValueError('Parent ' + pid + ' not found for node ' + nid)
            children[pid].append(nid)
    if root_id is None:
        raise ValueError('No root node')
    # Verify depths match actual depth from root
    def compute_depth(nid, depth):
        node = node_map[nid]
        if node['depth'] != depth:
            raise ValueError('Depth mismatch for node ' + nid)
        for child in children[nid]:
            compute_depth(child, depth+1)
    compute_depth(root_id, 0)
    # Check required symbols exist in original tree
    all_symbols = {node['symbol'] for node in nodes}
    for s in required_symbols:
        if s not in all_symbols:
            raise ValueError('Required symbol ' + s + ' not in tree')
    retained = set(node_map.keys())
    removal_order = []
    # Build candidate list: nodes that are removable, not root, not required symbol
    candidates = []
    for node in nodes:
        nid = node['id']
        if nid == root_id or node['symbol'] in required_symbols or not node['removable']:
            continue
        candidates.append(nid)
    # Sort: depth descending, then nid ascending
    candidates.sort(key=lambda nid: (-node_map[nid]['depth'], nid))
    for nid in candidates:
        if nid not in retained:
            continue
        node = node_map[nid]
        # Check if any children still retained
        has_retained_children = any(cid in retained for cid in children[nid])
        if has_retained_children:
            continue
        # Check if removing this node (and its subtree, but children are already gone)
        # only removes its own symbol
        # Test if required symbols still present
        temp_retained = retained - {nid}
        # Also consider descendants that are already removed - they are not in retained anyway
        retained_symbols = {node_map[x]['symbol'] for x in temp_retained}
        if required_symbols.issubset(retained_symbols):
            retained = temp_retained
            removal_order.append(nid)
    sorted_retained = sorted(retained)
    return {'retained_ids': sorted_retained, 'removal_order': removal_order}"
